bool AuditLogs::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("business_id"))
    {
        if(!validJsonOfField(1, "business_id", pJson["business_id"], err, true))
            return false;
    }
    else
    {
        err="The business_id column cannot be null";
        return false;
    }
    if(pJson.isMember("actor_id"))
    {
        if(!validJsonOfField(2, "actor_id", pJson["actor_id"], err, true))
            return false;
    }
    if(pJson.isMember("entity_type"))
    {
        if(!validJsonOfField(3, "entity_type", pJson["entity_type"], err, true))
            return false;
    }
    else
    {
        err="The entity_type column cannot be null";
        return false;
    }
    if(pJson.isMember("entity_id"))
    {
        if(!validJsonOfField(4, "entity_id", pJson["entity_id"], err, true))
            return false;
    }
    else
    {
        err="The entity_id column cannot be null";
        return false;
    }
    if(pJson.isMember("action"))
    {
        if(!validJsonOfField(5, "action", pJson["action"], err, true))
            return false;
    }
    else
    {
        err="The action column cannot be null";
        return false;
    }
    if(pJson.isMember("old_values"))
    {
        if(!validJsonOfField(6, "old_values", pJson["old_values"], err, true))
            return false;
    }
    if(pJson.isMember("new_values"))
    {
        if(!validJsonOfField(7, "new_values", pJson["new_values"], err, true))
            return false;
    }
    if(pJson.isMember("ip_address"))
    {
        if(!validJsonOfField(8, "ip_address", pJson["ip_address"], err, true))
            return false;
    }
    if(pJson.isMember("user_agent"))
    {
        if(!validJsonOfField(9, "user_agent", pJson["user_agent"], err, true))
            return false;
    }
    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(10, "created_at", pJson["created_at"], err, true))
            return false;
    }
    return true;
}
